<script lang="ts">
	import { onMount, tick } from 'svelte';
	import { apiData, type ApiSuccess } from '$lib/api';
	import AddButton from '$lib/components/AddButton.svelte';
	import AssetManagementShell from '$lib/components/AssetManagementShell.svelte';
	import DetailModal from '$lib/components/DetailModal.svelte';
	import DiscardChangesDialog from '$lib/components/DiscardChangesDialog.svelte';
	import FormSection from '$lib/components/FormSection.svelte';
	import MasterPageHeader from '$lib/components/MasterPageHeader.svelte';
	import MenuItemIcon from '$lib/components/MenuItemIcon.svelte';
	import ModalBackdrop from '$lib/components/ModalBackdrop.svelte';
	import SearchSelect from '$lib/components/SearchSelect.svelte';
	import SearchInput from '$lib/components/SearchInput.svelte';
	import WorkCalendarEntryModal, { type WorkCalendarEntry } from '$lib/components/WorkCalendarEntryModal.svelte';
	import { productName } from '$lib/brand';
	import { formSnapshot } from '$lib/modalForm';
	import { formatMonthYear, formatTimestamp, localization } from '$lib/localization';
	import '$lib/styles/action-menu.css';

	type WorkCalendar = { id: number; name: string; calendarYear: number; scheduledWorkMinutesPerDay: number; description: string | null; employeeCount: number; entryCount: number };
	type EmployeeReference = { id: number; name: string };
	type CalendarEmployee = { id: number; employeeCode: string; firstName: string; middleName: string | null; lastName: string; departmentRef: EmployeeReference | null; departments: EmployeeReference[]; group: EmployeeReference | null };
	type DateAttribute = { id: number; calendarDate: string; kind: 'sunday' | 'saturday' | 'public_holiday'; name: string };
	type HolidayImport = { id: number; status: 'success' | 'failed'; completedAt: string; importedCount: number; rangeStart: string | null; rangeEnd: string | null };
	const selectedCalendarStorageKey = 'work-calendars-selected-id';

	let calendars = $state<WorkCalendar[]>([]); let selectedId = $state<number | null>(null);
	let expandedCalendarYears = $state<number[]>([]);
	let entries = $state<WorkCalendarEntry[]>([]); let dateAttributes = $state<DateAttribute[]>([]);
	let assignedEmployees = $state<CalendarEmployee[]>([]); let employeeOptions = $state<CalendarEmployee[]>([]); let selectedEmployeeIds = $state<number[]>([]);
	let roles = $state<string[]>([]); let loading = $state(true); let detailLoading = $state(false); let saving = $state(false); let importing = $state(false);
	let message = $state(''); let error = $state(''); let showCalendarForm = $state(false); let editingCalendar = $state<WorkCalendar | null>(null);
	let calendarName = $state(''); let calendarYear = $state(''); let calendarHours = $state('7.75'); let calendarDescription = $state('');
	let calendarNameError = $state(''); let calendarYearError = $state(''); let calendarHoursError = $state(''); let calendarFormError = $state('');
	let selectedDate = $state(''); let selectedEntry = $state<WorkCalendarEntry | null>(null); let entryReturnFocus = $state<HTMLElement | null>(null);
	let employeeSearch = $state(''); let visibleMonth = $state(new Date(new Date().getFullYear(), new Date().getMonth(), 1)); let latestImport = $state<HolidayImport | null>(null);
	let calendarDialog = $state<HTMLDialogElement>(); let calendarNameInput = $state<HTMLInputElement>(); let calendarReturnFocus = $state<HTMLElement | null>(null); let addCalendarButton = $state<HTMLButtonElement>();
	let calendarInitialSnapshot = $state(''); let confirmingCalendarDiscard = $state(false);
	let calendarActionMenuOpen = $state(false); let calendarActionMenuTop = $state(0); let calendarActionMenuLeft = $state(0); let calendarActionTrigger = $state<HTMLButtonElement>();
	let showHolidayHelp = $state(false); let holidayHelpTrigger = $state<HTMLButtonElement>();
	const currentYear = new Date().getFullYear();
	const calendarYearOptions = Array.from({ length: currentYear + 20 - 2011 + 1 }, (_, index) => ({ value: String(currentYear + 20 - index), label: String(currentYear + 20 - index) }));

	let canManage = $derived(roles.includes('system_administrator'));
	let selectedCalendar = $derived(calendars.find((item) => item.id === selectedId) ?? null);
	let calendarGroups = $derived.by(() => {
		const groups = new Map<number, WorkCalendar[]>();
		for (const calendar of calendars) groups.set(calendar.calendarYear, [...(groups.get(calendar.calendarYear) ?? []), calendar]);
		return [...groups.entries()].sort(([left], [right]) => right - left).map(([year, items]) => ({ year, items }));
	});
	let assignmentDepartments = $derived.by(() => {
		const departments = new Map<number | null, { id: number | null; name: string; employees: CalendarEmployee[] }>();
		for (const employee of employeeOptions) {
			const id = employee.departmentRef?.id ?? null;
			const department = departments.get(id) ?? { id, name: employee.departmentRef?.name ?? 'No department', employees: [] };
			department.employees.push(employee); departments.set(id, department);
		}
		return [...departments.values()]
			.sort((left, right) => left.id === null ? 1 : right.id === null ? -1 : left.name.localeCompare(right.name, undefined, { numeric: true }))
			.map((department) => {
				const groups = new Map<number | null, { id: number | null; name: string; employees: CalendarEmployee[] }>();
				for (const employee of department.employees) {
					const id = employee.group?.id ?? null;
					const group = groups.get(id) ?? { id, name: employee.group?.name ?? 'No group', employees: [] };
					group.employees.push(employee); groups.set(id, group);
				}
				return { ...department, groups: [...groups.values()].sort((left, right) => left.id === null ? 1 : right.id === null ? -1 : left.name.localeCompare(right.name, undefined, { numeric: true })) };
			});
	});
	let filteredEmployees = $derived(employeeOptions.filter((employee) => `${employeeName(employee)} ${employee.employeeCode} ${employee.departments.map((department) => department.name).join(' ')} ${employee.group?.name ?? ''}`.toLowerCase().includes(employeeSearch.trim().toLowerCase())));
	let monthLabel = $derived(formatMonthYear(visibleMonth.getFullYear(), visibleMonth.getMonth(), $localization));
	let weekdayLabels = $derived($localization.displayLanguage === 'ja' ? ['日','月','火','水','木','金','土'] : ['Sun','Mon','Tue','Wed','Thu','Fri','Sat']);
	let calendarCells = $derived.by(() => {
		const year = visibleMonth.getFullYear(); const month = visibleMonth.getMonth(); const calendarScopeYear = selectedCalendar?.calendarYear ?? year; const start = new Date(year, month, 1 - new Date(year, month, 1).getDay()); const today = localDateIso(new Date());
		const entryMap = new Map(entries.map((entry) => [entry.workDate.slice(0, 10), entry])); const attributeMap = new Map<string, DateAttribute[]>();
		for (const attribute of dateAttributes) { const key = attribute.calendarDate.slice(0, 10); attributeMap.set(key, [...(attributeMap.get(key) ?? []), attribute]); }
		return Array.from({ length: 42 }, (_, index) => {
			const date = new Date(start); date.setDate(start.getDate() + index); const iso = localDateIso(date); const cellAttributes = attributeMap.get(iso) ?? []; const entry = entryMap.get(iso) ?? null;
			const holiday = cellAttributes.find((item) => item.kind === 'public_holiday'); const isSunday = cellAttributes.some((item) => item.kind === 'sunday') || date.getDay() === 0; const isSaturday = cellAttributes.some((item) => item.kind === 'saturday') || date.getDay() === 6;
			const isWorkingDay = entry?.entryType === 'working_day';
			const isRed = !isWorkingDay && Boolean(holiday || isSunday || entry?.entryType === 'company_holiday');
			return { iso, day: date.getDate(), inMonth: date.getMonth() === month, inCalendarYear: date.getFullYear() === calendarScopeYear, isToday: iso === today, entry, holiday, isWorkingDay, isRed, isBlue: !isWorkingDay && !isRed && isSaturday };
		});
	});
	let visibleEntryCount = $derived(calendarCells.filter((cell) => cell.inMonth && cell.entry).length);
	let calendarSummary = $derived.by(() => {
		if (!selectedCalendar) return { holidays: 0, workingDays: 0, annualMinutes: 0, weeklyMinutes: 0 };
		const year = selectedCalendar.calendarYear;
		const totalDays = Math.round((Date.UTC(year + 1, 0, 1) - Date.UTC(year, 0, 1)) / 86_400_000);
		const holidayDates = new Set(dateAttributes.map((attribute) => attribute.calendarDate.slice(0, 10)));
		const entryMap = new Map(entries.map((entry) => [entry.workDate.slice(0, 10), entry.entryType]));
		let workingDays = 0;
		for (let index = 0; index < totalDays; index += 1) {
			const date = new Date(Date.UTC(year, 0, index + 1));
			const iso = date.toISOString().slice(0, 10);
			const entryType = entryMap.get(iso);
			if (entryType === 'working_day' || (entryType !== 'company_holiday' && !holidayDates.has(iso) && date.getUTCDay() !== 0 && date.getUTCDay() !== 6)) workingDays += 1;
		}
		const annualMinutes = workingDays * selectedCalendar.scheduledWorkMinutesPerDay;
		return { holidays: totalDays - workingDays, workingDays, annualMinutes, weeklyMinutes: annualMinutes * 7 / totalDays };
	});
	let canMovePrevious = $derived(Boolean(selectedCalendar && visibleMonth > new Date(selectedCalendar.calendarYear, 0, 1)));
	let canMoveNext = $derived(Boolean(selectedCalendar && visibleMonth < new Date(selectedCalendar.calendarYear, 11, 1)));
	let canShowToday = $derived(selectedCalendar?.calendarYear === currentYear);
	let hasUnsavedCalendarChanges = $derived(Boolean(editingCalendar) && calendarInitialSnapshot !== '' && formSnapshot({ name: calendarName, year: calendarYear, hours: calendarHours, description: calendarDescription }) !== calendarInitialSnapshot);

	function localDateIso(date: Date) { return `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}-${String(date.getDate()).padStart(2, '0')}`; }
	function employeeName(employee: CalendarEmployee) { return [employee.firstName, employee.middleName, employee.lastName].filter(Boolean).join(' '); }
	function formatHoursAndMinutes(minutes: number) { const totalMinutes = Math.round(minutes); const hours = Math.floor(totalMinutes / 60); const remainingMinutes = totalMinutes % 60; return `${hours} ${hours === 1 ? 'hour' : 'hours'} ${remainingMinutes} ${remainingMinutes === 1 ? 'minute' : 'minutes'}`; }
	function indeterminate(node: HTMLInputElement, value: boolean) { node.indeterminate = value; return { update(nextValue: boolean) { node.indeterminate = nextValue; } }; }
	function selectionState(employees: CalendarEmployee[]) { const selectedCount = employees.reduce((count, employee) => count + Number(selectedEmployeeIds.includes(employee.id)), 0); return { selectedCount, all: employees.length > 0 && selectedCount === employees.length, some: selectedCount > 0 && selectedCount < employees.length }; }
	function storedCalendarId() { const value = Number(localStorage.getItem(selectedCalendarStorageKey)); return Number.isSafeInteger(value) && value > 0 ? value : null; }
	function rememberSelectedCalendar(id: number | null) { if (id) localStorage.setItem(selectedCalendarStorageKey, String(id)); else localStorage.removeItem(selectedCalendarStorageKey); }
	async function errorMessage(response: Response, fallback: string) { const payload = await response.clone().json().catch(() => null) as { error?: { message?: string } } | null; return payload?.error?.message ?? fallback; }
	async function fetchAll<T>(baseUrl: string): Promise<T[]> { const items: T[] = []; let offset = 0; for (;;) { const separator = baseUrl.includes('?') ? '&' : '?'; const response = await fetch(`${baseUrl}${separator}offset=${offset}&limit=500`); if (!response.ok) throw new Error(await errorMessage(response, 'Unable to load data.')); const payload = await response.json() as ApiSuccess<T[]>; items.push(...payload.data); if (!payload.meta?.hasMore) return items; offset += payload.data.length; } }

	async function loadCalendars(preferredId: number | null = selectedId) {
		calendars = await fetchAll<WorkCalendar>('/v1/work-calendars?sortBy=name&sortOrder=asc');
		selectedId = preferredId && calendars.some((item) => item.id === preferredId) ? preferredId : calendars[0]?.id ?? null;
		rememberSelectedCalendar(selectedId);
		const availableYears = new Set(calendars.map((calendar) => calendar.calendarYear));
		expandedCalendarYears = expandedCalendarYears.filter((year) => availableYears.has(year));
		const selectedYear = calendars.find((calendar) => calendar.id === selectedId)?.calendarYear;
		if (selectedYear !== undefined && !expandedCalendarYears.includes(selectedYear)) expandedCalendarYears = [...expandedCalendarYears, selectedYear];
	}
	async function loadAttributes() { const year = selectedCalendar?.calendarYear; if (!year) { dateAttributes = []; return; } dateAttributes = await fetchAll<DateAttribute>(`/v1/calendar-date-attributes?from=${year}-01-01&to=${year}-12-31&sortBy=calendarDate&sortOrder=asc`); }
	async function loadImportStatus() { const year = selectedCalendar?.calendarYear; if (!year) { latestImport = null; return; } const yearStart = `${year}-01-01`; const yearEnd = `${year}-12-31`; const imports = await fetchAll<HolidayImport>('/v1/calendar-holiday-imports?sortBy=completedAt&sortOrder=desc'); latestImport = imports.find((item) => item.status === 'success' && item.rangeStart && item.rangeEnd && item.rangeStart.slice(0, 10) <= yearEnd && item.rangeEnd.slice(0, 10) >= yearStart) ?? null; }
	async function loadSelected() {
		if (!selectedId) { entries = []; assignedEmployees = []; selectedEmployeeIds = []; return; } detailLoading = true; error = '';
		try { [entries, assignedEmployees] = await Promise.all([fetchAll<WorkCalendarEntry>(`/v1/work-calendars/${selectedId}/entries?sortBy=workDate&sortOrder=asc`), fetchAll<CalendarEmployee>(`/v1/work-calendars/${selectedId}/employees?sortBy=employee&sortOrder=asc`)]); selectedEmployeeIds = assignedEmployees.map((employee) => employee.id); }
		catch (caught) { error = caught instanceof Error ? caught.message : 'Unable to load the calendar.'; } finally { detailLoading = false; }
	}
	async function chooseCalendar(id: number) { closeCalendarActionMenu(); selectedId = id; rememberSelectedCalendar(id); selectedDate = ''; await loadSelected(); await showRelevantMonth(); await loadImportStatus(); }
	function toggleCalendarYear(year: number) { expandedCalendarYears = expandedCalendarYears.includes(year) ? expandedCalendarYears.filter((item) => item !== year) : [...expandedCalendarYears, year]; }
	async function showRelevantMonth(startInJanuary = false) {
		if (!selectedCalendar) return;
		const today = new Date(); const year = selectedCalendar.calendarYear; const prefix = `${year}-${String(today.getMonth() + 1).padStart(2, '0')}`;
		const relevant = startInJanuary ? null : entries.find((entry) => entry.workDate.startsWith(prefix)) ?? entries[0];
		const month = relevant ? new Date(`${relevant.workDate.slice(0, 10)}T00:00:00`).getMonth() : year === currentYear && !startInJanuary ? today.getMonth() : 0;
		visibleMonth = new Date(year, month, 1); await tick(); await loadAttributes();
	}
	async function moveMonth(offset: number) { if (!selectedCalendar) return; const next = new Date(visibleMonth.getFullYear(), visibleMonth.getMonth() + offset, 1); if (next.getFullYear() !== selectedCalendar.calendarYear) return; visibleMonth = next; }
	async function showToday() { if (!canShowToday) return; const today = new Date(); visibleMonth = new Date(today.getFullYear(), today.getMonth(), 1); }

	function selectCalendarCell(cell: (typeof calendarCells)[number], event: MouseEvent) { if (!canManage || !selectedId || !cell.inCalendarYear) return; selectedDate = cell.iso; selectedEntry = cell.entry; entryReturnFocus = event.currentTarget as HTMLElement; }
	function closeEntryModal() { selectedDate = ''; selectedEntry = null; }
	async function entrySaved(date: string, action: 'created' | 'updated' | 'deleted') { closeEntryModal(); await Promise.all([loadSelected(), loadCalendars(selectedId)]); message = action === 'deleted' ? 'Calendar entry deleted.' : action === 'updated' ? 'Calendar entry updated.' : 'Calendar entry added.'; const dateValue = new Date(`${date}T00:00:00`); visibleMonth = new Date(dateValue.getFullYear(), dateValue.getMonth(), 1); await tick(); await loadAttributes(); void tick().then(() => entryReturnFocus?.focus()); }

	function openCalendarForm(calendar: WorkCalendar | null, event?: MouseEvent, returnFocus?: HTMLElement | null) { editingCalendar = calendar; calendarName = calendar?.name ?? ''; calendarYear = String(calendar?.calendarYear ?? currentYear); calendarHours = String((calendar?.scheduledWorkMinutesPerDay ?? 465) / 60); calendarDescription = calendar?.description ?? ''; calendarNameError = ''; calendarYearError = ''; calendarHoursError = ''; calendarFormError = ''; calendarInitialSnapshot = formSnapshot({ name: calendarName, year: calendarYear, hours: calendarHours, description: calendarDescription }); confirmingCalendarDiscard = false; calendarReturnFocus = returnFocus ?? (event?.currentTarget as HTMLElement | undefined) ?? addCalendarButton ?? null; showCalendarForm = true; message = ''; error = ''; void tick().then(() => calendarNameInput?.focus()); }
	function closeCalendarActionMenu(focus = false) { calendarActionMenuOpen = false; if (focus) calendarActionTrigger?.focus(); }
	function toggleCalendarActionMenu(event: MouseEvent) {
		if (calendarActionMenuOpen) { closeCalendarActionMenu(true); return; }
		calendarActionTrigger = event.currentTarget as HTMLButtonElement;
		const rect = calendarActionTrigger.getBoundingClientRect(); const menuHeight = 86;
		calendarActionMenuTop = rect.bottom + menuHeight + 4 <= window.innerHeight ? rect.bottom + 4 : Math.max(8, rect.top - menuHeight - 4);
		calendarActionMenuLeft = Math.max(8, Math.min(rect.right - 160, window.innerWidth - 168));
		calendarActionMenuOpen = true;
		void tick().then(() => document.querySelector<HTMLButtonElement>('.calendar-action-menu [role="menuitem"]')?.focus());
	}
	function editCalendarFromMenu() { const trigger = calendarActionTrigger; closeCalendarActionMenu(); if (selectedCalendar) openCalendarForm(selectedCalendar, undefined, trigger); }
	function deleteCalendarFromMenu() { closeCalendarActionMenu(true); void deleteCalendar(); }
	function closeCalendarFormImmediately() { if (saving) return; confirmingCalendarDiscard = false; showCalendarForm = false; calendarInitialSnapshot = ''; void tick().then(() => calendarReturnFocus?.focus()); }
	function requestCloseCalendarForm() { if (saving) return; if (hasUnsavedCalendarChanges) { confirmingCalendarDiscard = true; return; } closeCalendarFormImmediately(); }
	async function saveCalendar() {
		const scheduledWorkMinutesPerDay = Math.round(Number(calendarHours) * 60);
		calendarNameError = calendarName.trim() ? '' : 'Name is required.'; calendarYearError = calendarYear ? '' : 'Year is required.'; calendarHoursError = Number.isFinite(Number(calendarHours)) && scheduledWorkMinutesPerDay >= 15 && scheduledWorkMinutesPerDay <= 1440 && scheduledWorkMinutesPerDay % 15 === 0 ? '' : 'Enter 0.25 to 24 hours in 0.25-hour increments.'; calendarFormError = '';
		if (!canManage || calendarNameError || calendarYearError || calendarHoursError) { await tick(); (calendarNameError ? calendarNameInput : calendarDialog?.querySelector<HTMLElement>('[aria-invalid="true"]'))?.focus(); return; }
		saving = true; message = '';
		const response = await fetch(editingCalendar ? `/v1/work-calendars/${editingCalendar.id}` : '/v1/work-calendars', { method: editingCalendar ? 'PATCH' : 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ name: calendarName.trim(), calendarYear: Number(calendarYear), scheduledWorkMinutesPerDay, description: calendarDescription.trim() || null }) });
		if (!response.ok) {
			calendarFormError = await errorMessage(response, 'Unable to save the calendar.');
			const payload = await response.clone().json().catch(() => null) as { error?: { details?: Array<{ field?: string }> } } | null;
			if (payload?.error?.details?.some((detail) => detail.field === 'name')) { calendarNameError = calendarFormError; await tick(); calendarNameInput?.focus(); }
		}
		else { const wasEditing = Boolean(editingCalendar); const saved = await apiData<WorkCalendar>(response); showCalendarForm = false; await loadCalendars(saved.id); await loadSelected(); await showRelevantMonth(!wasEditing); message = wasEditing ? 'Calendar updated.' : 'Calendar created.'; }
		saving = false;
	}
	async function deleteCalendar() { if (!canManage || !selectedCalendar || !confirm(`Delete ${selectedCalendar.name}? Employee assignments will be cleared.`)) return; saving = true; error = ''; message = ''; const response = await fetch(`/v1/work-calendars/${selectedCalendar.id}`, { method: 'DELETE' }); if (!response.ok) error = await errorMessage(response, 'Unable to delete the calendar.'); else { await loadCalendars(null); await loadSelected(); message = 'Calendar deleted.'; } saving = false; }
	async function refreshHolidays() { const target = selectedCalendar; if (!canManage || !target) return; importing = true; error = ''; message = ''; const response = await fetch('/v1/calendar-holiday-imports', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ workCalendarId: target.id }) }); if (!response.ok) error = await errorMessage(response, 'Unable to refresh public holidays.'); else { await Promise.all([loadAttributes(), loadImportStatus()]); message = `Public holidays for ${target.calendarYear} refreshed from the Cabinet Office.`; } importing = false; }
	function toggleEmployee(id: number) { selectedEmployeeIds = selectedEmployeeIds.includes(id) ? selectedEmployeeIds.filter((employeeId) => employeeId !== id) : [...selectedEmployeeIds, id]; }
	function toggleEmployees(employees: CalendarEmployee[]) { const ids = employees.map((employee) => employee.id); const selected = new Set(selectedEmployeeIds); if (ids.every((id) => selected.has(id))) ids.forEach((id) => selected.delete(id)); else ids.forEach((id) => selected.add(id)); selectedEmployeeIds = [...selected]; }
	async function saveAssignments() { if (!canManage || !selectedId) return; saving = true; error = ''; message = ''; const response = await fetch(`/v1/work-calendars/${selectedId}/employees`, { method: 'PUT', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ employeeIds: selectedEmployeeIds }) }); if (!response.ok) error = await errorMessage(response, 'Unable to save employee assignments.'); else { await loadSelected(); await loadCalendars(selectedId); message = 'Employee assignments updated.'; } saving = false; }
	function calendarModalKeydown(event: KeyboardEvent) { if (event.key === 'Escape' && calendarActionMenuOpen) { event.preventDefault(); closeCalendarActionMenu(true); return; } if (!showCalendarForm || confirmingCalendarDiscard || !calendarDialog || event.defaultPrevented) return; if (event.key === 'Escape') { event.preventDefault(); requestCloseCalendarForm(); return; } if (event.key !== 'Tab') return; const controls = [...calendarDialog.querySelectorAll<HTMLElement>('button:not([disabled]),input:not([disabled]),textarea:not([disabled])')].filter((item) => item.getClientRects().length); const first = controls[0]; const last = controls.at(-1); if (!first || !last) return; if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last.focus(); } else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first.focus(); } }

	onMount(() => { void (async () => { try { const response = await fetch('/v1/auth/session'); if (!response.ok) throw new Error('Authentication is required.'); roles = (await apiData<{ user: { roles: string[] } }>(response)).user.roles; await loadCalendars(storedCalendarId()); if (canManage) employeeOptions = await fetchAll<CalendarEmployee>('/v1/employees?sortBy=employee&sortOrder=asc'); await loadSelected(); await showRelevantMonth(); await loadImportStatus(); } catch (caught) { error = caught instanceof Error ? caught.message : 'Unable to load work calendars.'; } finally { loading = false; } })(); });
	onMount(() => { const outside = (event: MouseEvent) => { if (!(event.target as Element).closest('.calendar-action-menu,.calendar-kebab')) closeCalendarActionMenu(); }; const scroll = () => closeCalendarActionMenu(); document.addEventListener('click', outside); window.addEventListener('scroll', scroll, true); return () => { document.removeEventListener('click', outside); window.removeEventListener('scroll', scroll, true); }; });
</script>

<svelte:window onkeydown={calendarModalKeydown} />
<svelte:head><title>Work calendars · {productName}</title></svelte:head>
<AssetManagementShell title="Work calendars">
	<div class="calendar-page">
		<MasterPageHeader title="Work calendars" description="Review calendar entries and the employees assigned to each calendar.">{#snippet actions()}{#if canManage}<AddButton bind:element={addCalendarButton} label="Add calendar" onclick={(event) => openCalendarForm(null, event)} />{/if}{/snippet}</MasterPageHeader>
		{#if message}<p class="notice success" role="status">{message}</p>{/if}{#if error}<p class="notice error" role="alert">{error}</p>{/if}
		{#if loading}<section class="empty">Loading work calendars…</section>{:else}<div class="layout">
			<section class="calendar-list" aria-label="Work calendars"><header><h2>Calendars</h2><span hidden>{calendars.length}</span></header>{#if !calendars.length}<p>No calendars found.</p>{:else}<div class="calendar-groups">{#each calendarGroups as group}{@const expanded = expandedCalendarYears.includes(group.year)}<section class="calendar-year-group"><button class="calendar-year-toggle" type="button" aria-expanded={expanded} aria-controls={`calendar-year-${group.year}`} onclick={() => toggleCalendarYear(group.year)}><span>{group.year}</span><span class="calendar-year-count" aria-label={`${group.items.length} ${group.items.length === 1 ? 'calendar' : 'calendars'}`}>{group.items.length}</span><svg class:expanded viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><path d="m4 6 4 4 4-4" /></svg></button><div class="calendar-items" id={`calendar-year-${group.year}`} hidden={!expanded}>{#each group.items as calendar}<button type="button" class:active={calendar.id === selectedId} onclick={() => void chooseCalendar(calendar.id)}><strong>{calendar.name}</strong><span>{calendar.entryCount} entries · {calendar.employeeCount} employees</span></button>{/each}</div></section>{/each}</div>{/if}</section>
			{#if selectedCalendar}<div class="details" class:busy={detailLoading}>
				<section class="summary"><div class="summary-main"><p class="calendar-year">{selectedCalendar.calendarYear}</p><h2>{selectedCalendar.name}</h2><p class="calendar-description">{selectedCalendar.description || 'No description.'}</p></div>{#if canManage}<button bind:this={calendarActionTrigger} class="kebab-button calendar-kebab calendar-action-trigger" type="button" aria-label={`Actions for ${selectedCalendar.name}`} aria-haspopup="menu" aria-expanded={calendarActionMenuOpen} onclick={toggleCalendarActionMenu}><svg viewBox="0 0 16 16" fill="currentColor" aria-hidden="true"><circle cx="3" cy="8" r="1.4"/><circle cx="8" cy="8" r="1.4"/><circle cx="13" cy="8" r="1.4"/></svg></button>{/if}<div class="summary-side"><dl class="calendar-stats"><div><dt>Annual holidays</dt><dd>{calendarSummary.holidays} days</dd></div><div><dt>Annual working days</dt><dd>{calendarSummary.workingDays} days</dd></div><div><dt>Scheduled hours / day</dt><dd>{formatHoursAndMinutes(selectedCalendar.scheduledWorkMinutesPerDay)}</dd></div><div><dt>Annual working hours</dt><dd>{formatHoursAndMinutes(calendarSummary.annualMinutes)}</dd></div><div><dt>Average weekly hours</dt><dd>{formatHoursAndMinutes(calendarSummary.weeklyMinutes)}</dd></div></dl></div></section>
				<section class="panel calendar-panel"><header class="calendar-toolbar"><div><h3>Calendar {selectedCalendar.calendarYear}</h3><p>{visibleEntryCount} entries in {monthLabel}.{#if canManage} Click a date to add or edit an entry.{/if}</p></div><div class="calendar-actions">{#if canManage}<div class="holiday-refresh-actions"><button class="secondary-action refresh" type="button" disabled={importing} onclick={() => void refreshHolidays()}>{importing ? 'Refreshing…' : 'Refresh holidays'}</button><button bind:this={holidayHelpTrigger} class="holiday-help-button" type="button" aria-label="About refreshing public holidays" title="About refreshing public holidays" onclick={() => showHolidayHelp = true}><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><circle cx="12" cy="12" r="10"/><path d="M9.1 9a3 3 0 015.8 1c0 2-3 3-3 3"/><circle cx="12" cy="17" r="0.5" fill="currentColor"/></svg></button></div>{/if}<div class="month-controls"><button type="button" disabled={!canMovePrevious} aria-label="Previous month" onclick={() => void moveMonth(-1)}>‹</button><button type="button" disabled={!canShowToday} onclick={() => void showToday()}>Today</button><strong aria-live="polite">{monthLabel}</strong><button type="button" disabled={!canMoveNext} aria-label="Next month" onclick={() => void moveMonth(1)}>›</button></div></div></header>
					{#if latestImport}<p class="import-status">Holidays for {selectedCalendar.calendarYear} last refreshed {formatTimestamp(latestImport.completedAt, $localization)} · {latestImport.importedCount} records</p>{/if}
					<div class="month-scroll"><div class="month-grid" aria-label={`${monthLabel} work calendar`}>{#each weekdayLabels as weekday, index}<div class="weekday" class:sunday={index===0} class:saturday={index===6}>{weekday}</div>{/each}{#each calendarCells as cell}<button type="button" class="day-cell" class:outside={!cell.inMonth || !cell.inCalendarYear} class:today={cell.isToday} class:red-day={cell.isRed} class:blue-day={cell.isBlue} class:working-day={cell.isWorkingDay} class:has-entry={Boolean(cell.entry)} disabled={!canManage || !cell.inCalendarYear} aria-label={`${cell.iso}${cell.holiday ? `, ${cell.holiday.name}` : ''}${cell.entry ? `, ${cell.entry.title}` : ''}`} onclick={(event) => selectCalendarCell(cell,event)}><span class="day-number">{cell.day}</span>{#if cell.holiday}<span class="holiday-name">{cell.holiday.name}</span>{/if}{#if cell.entry}<span class:holiday-entry={cell.entry.entryType==='company_holiday'} class="entry-type">{cell.entry.entryType==='company_holiday'?'Company holiday':'Working day'}</span><small>{cell.entry.title}</small>{/if}</button>{/each}</div></div>
				</section>
				<section class="panel"><header><div><h3>Assigned employees</h3><p>Each employee can use one work calendar.</p></div>{#if canManage}<button class="app-primary-action" type="button" disabled={saving} onclick={() => void saveAssignments()}>Save assignments</button>{/if}</header>{#if canManage}<section class="selection-section bulk-assignment" aria-labelledby="bulk-assignment-title"><div class="selection-heading"><h4 id="bulk-assignment-title">Select by department or group</h4><p>Selections apply to every employee in the department or group.</p></div><div class="department-grid">{#each assignmentDepartments as department}{@const departmentState = selectionState(department.employees)}<section class="department-card"><label class="department-option"><input type="checkbox" checked={departmentState.all} use:indeterminate={departmentState.some} onchange={() => toggleEmployees(department.employees)} /><span><strong>{department.name}</strong><small>{departmentState.selectedCount} of {department.employees.length} selected</small></span></label><div class="group-options">{#each department.groups as group}{@const groupState = selectionState(group.employees)}<label><input type="checkbox" checked={groupState.all} use:indeterminate={groupState.some} onchange={() => toggleEmployees(group.employees)} /><span>{group.name}</span><small>{groupState.selectedCount}/{group.employees.length}</small></label>{/each}</div></section>{:else}<p>No departments or groups found.</p>{/each}</div></section><section class="selection-section employee-assignment" aria-labelledby="employee-assignment-title"><div class="selection-heading"><h4 id="employee-assignment-title">Select by employee</h4></div><div class="employee-search-row"><SearchInput label="Search employees" value={employeeSearch} onValueChange={(value) => employeeSearch = value} /></div><div class="employee-grid">{#each filteredEmployees as employee}<label><input type="checkbox" checked={selectedEmployeeIds.includes(employee.id)} onchange={() => toggleEmployee(employee.id)} /><span><strong>{employeeName(employee)}</strong><small>{employee.employeeCode} · {employee.departmentRef?.name ?? 'No department'} · {employee.group?.name ?? 'No group'}</small></span></label>{:else}<p>No employees found.</p>{/each}</div><p class="hint">Selecting an employee currently assigned elsewhere moves that employee to this calendar.</p></section>{:else}<ul class="assigned-list">{#each assignedEmployees as employee}<li><span>{employeeName(employee)}</span><small>{employee.employeeCode}</small></li>{:else}<li>No employees assigned.</li>{/each}</ul>{/if}</section>
			</div>{:else}<section class="empty detail-empty">Select or create a calendar.</section>{/if}
		</div>{/if}
	</div>
	{#if calendarActionMenuOpen && selectedCalendar}<div class="menu-popover calendar-action-menu" role="menu" style={`top:${calendarActionMenuTop}px;left:${calendarActionMenuLeft}px`}><button type="button" role="menuitem" onclick={editCalendarFromMenu}><MenuItemIcon name="edit" />Edit</button><div class="menu-separator"></div><button type="button" class="delete-item" role="menuitem" disabled={saving} onclick={deleteCalendarFromMenu}><MenuItemIcon name="delete" />Delete</button></div>{/if}
	{#if showHolidayHelp}<DetailModal title="About Refresh holidays" titleId="holiday-refresh-help-title" closeLabel="Close holiday refresh help" returnFocus={holidayHelpTrigger} compact dialogClass="holiday-help-dialog" onClose={() => showHolidayHelp = false}><div class="holiday-help-content"><p>Refresh holidays manually synchronizes Japan's public holidays from the Cabinet Office for the year of the calendar currently displayed. It is usually needed only during initial setup, when holidays for a future year are published, or when an official holiday is corrected.</p><section class="app-detail-section"><h3>What it updates</h3><ul><li>Public holiday records for the displayed calendar year only</li><li>Holiday names and holiday styling in calendars for that year</li><li>Annual holidays, working days, and working hours</li></ul></section><section class="app-detail-section"><h3>Important</h3><ul><li>Calendars for other years are not changed. Calendars in the same year share the same public holiday data.</li><li>Company-specific days off are added separately as <strong>Company holiday</strong> entries.</li><li>A <strong>Working day</strong> entry overrides a public holiday for that calendar.</li><li>If the refresh fails, the existing holiday data is kept.</li></ul></section></div></DetailModal>{/if}
	{#if selectedDate && selectedId}<WorkCalendarEntryModal calendarId={selectedId} workDate={selectedDate} entry={selectedEntry} returnFocus={entryReturnFocus} onClose={closeEntryModal} onSaved={entrySaved} />{/if}
	{#if showCalendarForm}
		<ModalBackdrop onDismiss={requestCloseCalendarForm} disabled={saving}>
			<dialog bind:this={calendarDialog} class="app-modal app-modal--compact calendar-dialog" open aria-modal="true" aria-labelledby="calendar-form-title">
				<header><h2 id="calendar-form-title">{editingCalendar ? 'Edit calendar' : 'Add calendar'}</h2><button class="app-modal-close" type="button" aria-label="Close calendar form" disabled={saving} onclick={requestCloseCalendarForm}><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><path d="M6 6l12 12M18 6 6 18" /></svg></button></header>
				<form class="app-modal-form" novalidate onsubmit={(event) => { event.preventDefault(); void saveCalendar(); }}>
					<div class="app-modal-form-body calendar-form-body">
						{#if calendarFormError}<div class="app-modal-error-summary" role="alert"><strong>Unable to save calendar</strong><span>{calendarFormError}</span></div>{/if}
						<FormSection title="Calendar details" columns={2} framed>
							<label><span>Name <span class="required" aria-hidden="true">*</span></span><input bind:this={calendarNameInput} required maxlength="128" bind:value={calendarName} class:invalid={Boolean(calendarNameError)} aria-invalid={Boolean(calendarNameError)} aria-describedby={calendarNameError ? 'calendar-name-error' : undefined} oninput={() => { calendarNameError = ''; calendarFormError = ''; }} />{#if calendarNameError}<small id="calendar-name-error" class="field-error" role="alert">{calendarNameError}</small>{/if}</label>
							<SearchSelect label="Year" field="calendarYear" value={calendarYear} options={calendarYearOptions} required disabled={Boolean(editingCalendar)} error={calendarYearError} onSelect={(value) => { calendarYear = value; calendarYearError = ''; calendarFormError = ''; }} />
							<label><span>Scheduled working hours / day <span class="required" aria-hidden="true">*</span></span><input type="number" min="0.25" max="24" step="0.25" required bind:value={calendarHours} class:invalid={Boolean(calendarHoursError)} aria-invalid={Boolean(calendarHoursError)} aria-describedby={calendarHoursError ? 'calendar-hours-error' : 'calendar-hours-hint'} oninput={() => { calendarHoursError = ''; calendarFormError = ''; }} />{#if calendarHoursError}<small id="calendar-hours-error" class="field-error" role="alert">{calendarHoursError}</small>{:else}<small id="calendar-hours-hint" class="field-hint">Enter hours in 0.25-hour increments.</small>{/if}</label>
							<label class="wide"><span>Description</span><textarea maxlength="1000" rows="4" bind:value={calendarDescription}></textarea></label>
						</FormSection>
					</div>
					<footer class="app-modal-footer"><button class="secondary" type="button" disabled={saving} onclick={requestCloseCalendarForm}>Cancel</button><button class="app-primary-action" type="submit" disabled={saving}>{saving ? 'Saving…' : editingCalendar ? 'Save changes' : 'Add calendar'}</button></footer>
				</form>
			</dialog>
		</ModalBackdrop>
		{#if confirmingCalendarDiscard}<DiscardChangesDialog onContinue={() => confirmingCalendarDiscard = false} onDiscard={closeCalendarFormImmediately} />{/if}
	{/if}
</AssetManagementShell>

<style>
	.calendar-page{min-width:0}.layout{display:grid;grid-template-columns:260px minmax(0,1fr);gap:18px;align-items:start}.calendar-list,.summary,.panel,.empty{background:var(--surface);border:1px solid var(--border);border-radius:6px;box-shadow:var(--shadow)}.calendar-list{position:sticky;top:72px;overflow:hidden}.calendar-list>header{display:flex;align-items:center;justify-content:space-between;padding:14px 16px;border-bottom:1px solid var(--border)}.calendar-list h2{margin:0;font-size:14px}.calendar-list header span{color:var(--muted);font-size:12px}.calendar-list>p{padding:8px 16px;color:var(--muted);font-size:13px}.calendar-year-group:not(:last-child){border-bottom:1px solid var(--border)}.calendar-year-toggle{display:grid;grid-template-columns:1fr auto 14px;align-items:center;gap:8px;width:100%;height:38px;margin:0;padding:0 12px;background:var(--surface-secondary)!important;color:var(--text)!important;border:0;border-radius:0;text-align:left}.calendar-year-toggle:hover{background:var(--border-light)!important}.calendar-year-toggle>span:first-child{font-size:12px;font-weight:700}.calendar-year-count{display:inline-flex;align-items:center;justify-content:center;min-width:22px;height:20px;padding:0 6px;background:rgba(51,122,183,.12);color:#337ab7!important;border:1px solid rgba(51,122,183,.28);border-radius:999px;font-size:10px!important;font-weight:700}.calendar-year-toggle svg{width:14px;height:14px;transition:transform .16s ease}.calendar-year-toggle svg.expanded{transform:rotate(180deg)}.calendar-items>button{display:flex;flex-direction:column;align-items:flex-start;width:100%;margin:0;padding:12px 16px;background:transparent;color:var(--text);border:0;border-bottom:1px solid var(--border-light);border-radius:0;text-align:left}.calendar-items>button:last-child{border-bottom:0}.calendar-items>button:hover,.calendar-items>button.active{background:var(--surface-secondary)}.calendar-items>button.active{box-shadow:inset 3px 0 var(--primary)}.calendar-list strong{font-size:13px}.calendar-items>button span{color:var(--muted);font-size:11px}.details{display:grid;gap:18px;min-width:0}.details.busy{opacity:.7}.summary{position:relative;display:flex;align-items:flex-start;justify-content:space-between;gap:18px;flex-wrap:wrap;padding:18px 56px 18px 18px}.summary-main{min-width:0;max-width:70ch;flex:1 1 240px}.calendar-year{margin:0;color:var(--primary);font-size:11px;font-weight:700}.summary h2{margin:3px 0;font-size:20px;overflow-wrap:anywhere}.calendar-description{margin:8px 0 0;white-space:pre-wrap;overflow-wrap:anywhere;word-break:break-word;color:var(--muted);font-size:13px;line-height:1.55}.summary-side{min-width:0;max-width:100%;flex:0 1 auto;align-self:flex-end}.calendar-stats{display:grid;grid-template-columns:repeat(5,max-content);width:max-content;max-width:100%;gap:1px;margin:0;overflow:hidden;background:var(--border-light);border:1px solid var(--border-light);border-radius:5px}.calendar-stats div{min-width:0;padding:8px 10px;background:var(--surface-secondary)}.calendar-stats dt{white-space:nowrap;color:var(--muted);font-size:10px;line-height:1.25}.calendar-stats dd{margin:4px 0 0;color:var(--text);font-size:13px;font-weight:700;white-space:nowrap}.calendar-actions,.month-controls{display:flex;align-items:center;gap:6px}.secondary-action{display:inline-flex;align-items:center;justify-content:center;box-sizing:border-box;height:32px;margin:0;padding:0 12px;border-radius:4px;font-size:12.5px;font-weight:500;line-height:1}.secondary-action{background:var(--surface)!important;color:var(--text-secondary)!important;border:1px solid var(--border);box-shadow:var(--shadow)}.panel{min-width:0;padding:18px}.panel>header{display:flex;align-items:flex-start;justify-content:space-between;gap:14px;margin-bottom:14px}.panel h3{margin:0;font-size:15px}.panel header p{margin:3px 0 0;color:var(--muted);font-size:12px}.calendar-toolbar{align-items:center!important}.month-controls button{min-width:34px;height:32px;margin:0;padding:0 9px;back