	.selection-section{container-name:employee-selection;container-type:inline-size;padding:12px;background:var(--surface-secondary);border:1px solid var(--border-light);border-radius:6px}.bulk-assignment{margin-bottom:14px}.selection-heading{margin-bottom:10px}.selection-heading h4{margin:0;font-size:13px}.selection-heading p{margin:3px 0 0;color:var(--muted);font-size:11px}.department-grid,.employee-grid{grid-template-columns:repeat(5,minmax(0,1fr))}.department-grid{display:grid;gap:8px}.department-card{overflow:hidden;background:var(--surface);border:1px solid var(--border);border-radius:5px}.department-option{display:flex;align-items:center;gap:9px;padding:9px 10px;border-bottom:1px solid var(--border-light);cursor:pointer}.department-option>span{display:flex;flex-direction:column;min-width:0}.department-option strong{overflow:hidden;font-size:12px;text-overflow:ellipsis;white-space:nowrap}.department-option small{color:var(--muted);font-size:10px}.group-options{display:grid;gap:1px;padding:6px}.group-options label{display:grid;grid-template-columns:16px minmax(0,1fr) auto;align-items:center;gap:7px;padding:6px;border-radius:4px;cursor:pointer;font-size:11px}.group-options label:hover,.department-option:hover{background:var(--surface-secondary)}.group-options small{color:var(--muted);font-size:10px}.selection-section input{width:15px;height:15px}.employee-grid{max-height:none;overflow:visible}.employee-grid small{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
	@container employee-selection (max-width:1279px){.department-grid,.employee-grid{grid-template-columns:repeat(4,minmax(0,1fr))}}
	@container employee-selection (max-width:1079px){.department-grid,.employee-grid{grid-template-columns:repeat(3,minmax(0,1fr))}}
	@container employee-selection (max-width:759px){.department-grid,.employee-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}
	@container employee-selection (max-width:519px){.department-grid,.employee-grid{grid-template-columns:1fr}}
	.calendar-action-trigger{position:absolute;z-index:1;top:14px;right:14px}
